const main = async () => {
    const api = new API(pm);
    const rnd = new RandomUtils();

    let event;
    try {
        const user = await api.addUser(rnd.getUser());
        pm.collectionVariables.set("uid", user.id)
        const user2 = await api.addUser(rnd.getUser());
        pm.collectionVariables.set("uid2", user2.id)
        const category = await api.addCategory(rnd.getCategory());
        event = rnd.getEvent(category.id);
        event = await api.addEvent(user.id, event);
        pm.collectionVariables.set("event", event.id);
    } catch(err) {
        console.error("Ошибка при подготовке тестовых данных.", err);
    }

    pm.request.body.update({
        mode: 'raw',
        raw: JSON.stringify(rnd.getComment()),
        options: { raw: { language: 'json' } }
    });
};

const interval = setInterval(() => {}, 1000);

setTimeout(async () => 
    {
        try {
            await main();
        } catch (e) {
            console.error(e);
        } finally {
            clearInterval(interval);
        }
    },  
    100 
);

pm.test("Ответ должен содержать код статуса 201 и данные в формате json", function () {
    pm.response.to.have.status(201);  
    pm.response.to.be.withBody;
    pm.response.to.be.json;
});

const source = JSON.parse(pm.request.body.raw);
const target = pm.response.json();

pm.test("Комментарий должно содержать поля: id, text, eventId, authorId, created", function () {
pm.expect(target).to.have.property('id');
pm.expect(target).to.have.property('text');
pm.expect(target).to.have.property('eventId');
pm.expect(target).to.have.property('authorId');
pm.expect(target).to.have.property('created');
});

pm.test("Данные в ответе должны соответствовать данным в запросе", function () {
    pm.expect(target.id).to.not.be.null;
